export class TaskChecklist {
  private readonly service = inject(TaskService);

  readonly projectId = input.required<number>();
  readonly taskId = input.required<number>();
  readonly taskTitle = input.required<string>();
  readonly items = input<ChecklistItem[]>([]);

  protected readonly checklist = linkedSignal(() => this.items());
  protected readonly doneCount = computed(() => this.checklist().filter((i) => i.done).length);
  protected readonly saving = signal(false);
  protected readonly saveError = signal<string | null>(null);
  protected readonly toggling = signal<number | null>(null);
  protected readonly toggleError = signal<string | null>(null);

  protected readonly form = inject(NonNullableFormBuilder).group({
    text: ['', [Validators.required, Validators.maxLength(255)]],
  });

  protected add(): void {
    const text = this.form.getRawValue().text.trim();
    if (this.form.invalid || !text) {
      this.form.reset();
      return;
    }
    this.saving.set(true);
    this.saveError.set(null);
    this.service.addChecklistItem(this.projectId(), this.taskId(), text).subscribe({
      next: (created) => {
        this.checklist.update((list) => [...list, created]);
        this.form.reset();
        this.saving.set(false);
      },
      error: () => {
        this.saveError.set('Could not add the checklist item. Please try again.');
        this.saving.set(false);
      },
    });
  }

  protected toggle(item: ChecklistItem, event: Event): void {
    const checkbox = event.target as HTMLInputElement;
    this.toggling.set(item.id);
    this.toggleError.set(null);
    this.service.toggleChecklistItem(this.projectId(), this.taskId(), item.id).subscribe({
      next: (updated) => {
        this.checklist.update((list) => list.map((i) => (i.id === updated.id ? updated : i)));
        this.toggling.set(null);
      },
      error: () => {
        this.toggleError.set('Could not update the checklist item. Please try again.');
        checkbox.checked = item.done;
        this.toggling.set(null);
      },
    });
  }
}
